import { parse } from "@babel/parser";
import traverse from "@babel/traverse";
import generator from "@babel/generator";
import * as t from "@babel/types";
/**
 * Colors for logging (ANSI escape codes).
 */
const COLORS = {
    reset: "\x1b[0m",
    green: "\x1b[32m",
    yellow: "\x1b[33m",
    cyan: "\x1b[36m",
    bold: "\x1b[1m",
};
const LOG_PREFIX = `${COLORS.cyan}[REACT-ADAPTER]${COLORS.reset}`;
/**
 * Logical module name from which the host exports React bindings.
 */
const LOGICAL_MODULE_NAME = "react";
/**
 * Names used by the host application to export React-related bindings.
 */
const HOST_EXPORTS = {
    reactDefault: "React",
    reactNamed: "reactExports",
    jsxRuntime: "jsxRuntimeExports",
    reactDOMClient: "ReactDOM",
};
function getDefaultFunc(func) {
    return func?.default || func;
}
/**
 * Vite plugin to adapt React and React-related imports to the host's export format.
 * This ensures plugin code can use standard React imports, while at runtime all
 * references resolve to the host's exports (single "react" entrypoint).
 *
 * @returns {Plugin} Vite plugin object
 */
export function viteReactHostImportAdapter() {
    const traverseFunc = getDefaultFunc(traverse);
    const generatorFunc = getDefaultFunc(generator);
    return {
        name: "vite-react-host-import-adapter",
        async transform(code, id) {
            // Only process project JS/TS files (skip node_modules)
            if (!/\.(t|j)sx?$/.test(id) || id.includes("node_modules")) {
                return null;
            }
            // Parse code into an AST
            const ast = parse(code, {
                sourceType: "module",
                plugins: ["jsx", "typescript"],
                sourceFilename: id,
            });
            // Collect info about encountered React-related imports
            const collectedImports = {
                react: {
                    default: null,
                    named: [],
                    needsImport: false,
                },
                jsxRuntime: { named: [], needsImport: false },
                client: { named: [], needsImport: false },
            };
            let requiresTransformation = false;
            // Visit and remove original React imports
            traverseFunc(ast, {
                ImportDeclaration(path) {
                    const source = path.node.source.value;
                    let target = null;
                    if (source === "react")
                        target = collectedImports.react;
                    else if (source === "react/jsx-runtime")
                        target = collectedImports.jsxRuntime;
                    else if (source === "react-dom/client")
                        target = collectedImports.client;
                    if (target) {
                        requiresTransformation = true;
                        target.needsImport = true;
                        path.node.specifiers.forEach((spec) => {
                            if (t.isImportDefaultSpecifier(spec)) {
                                // Only 'react' import has a 'default' property
                                if (target === collectedImports.react) {
                                    target.default = spec.local.name;
                                }
                            }
                            else if (t.isImportSpecifier(spec)) {
                                target.named.push({
                                    imported: t.isIdentifier(spec.imported)
                                        ? spec.imported.name
                                        : spec.imported
                                            .value,
                                    local: spec.local.name,
                                });
                            }
                        });
                        // Remove original import
                        path.remove();
                    }
                },
            });
            if (!requiresTransformation) {
                return null;
            }
            // Generate new consolidated import from the host's "react" module
            const importSpecifiers = [];
            if (collectedImports.react.needsImport) {
                importSpecifiers.push(t.importSpecifier(t.identifier(HOST_EXPORTS.reactDefault), t.identifier(HOST_EXPORTS.reactDefault)), t.importSpecifier(t.identifier(HOST_EXPORTS.reactNamed), t.identifier(HOST_EXPORTS.reactNamed)));
            }
            if (collectedImports.jsxRuntime.needsImport) {
                importSpecifiers.push(t.importSpecifier(t.identifier(HOST_EXPORTS.jsxRuntime), t.identifier(HOST_EXPORTS.jsxRuntime)));
            }
            if (collectedImports.client.needsImport) {
                importSpecifiers.push(t.importSpecifier(t.identifier(HOST_EXPORTS.reactDOMClient), t.identifier(HOST_EXPORTS.reactDOMClient)));
            }
            const newNodes = [];
            if (importSpecifiers.length > 0) {
                newNodes.push(t.importDeclaration(importSpecifiers, t.stringLiteral(LOGICAL_MODULE_NAME)));
            }
            // Map the host's exports to the local variable names expected in user code
            if (collectedImports.react.default) {
                newNodes.push(t.variableDeclaration("const", [
                    t.variableDeclarator(t.identifier(collectedImports.react.default), t.identifier(HOST_EXPORTS.reactDefault)),
                ]));
            }
            collectedImports.react.named.forEach((spec) => {
                newNodes.push(t.variableDeclaration("const", [
                    t.variableDeclarator(t.identifier(spec.local), t.memberExpression(t.identifier(HOST_EXPORTS.reactNamed), t.identifier(spec.imported))),
                ]));
            });
            collectedImports.jsxRuntime.named.forEach((spec) => {
                newNodes.push(t.variableDeclaration("const", [
                    t.variableDeclarator(t.identifier(spec.local), t.memberExpression(t.identifier(HOST_EXPORTS.jsxRuntime), t.identifier(spec.imported))),
                ]));
            });
            collectedImports.client.named.forEach((spec) => {
                newNodes.push(t.variableDeclaration("const", [
                    t.variableDeclarator(t.identifier(spec.local), t.memberExpression(t.identifier(HOST_EXPORTS.reactDOMClient), t.identifier(spec.imported))),
                ]));
            });
            // Insert new nodes at the start of the file
            ast.program.body.unshift(...newNodes);
            // Generate the new code and sourcemap
            const output = generatorFunc(ast, {
                sourceMaps: true,
                sourceFileName: id,
            }, code);
            // Log transformation with file name, in green
            console.log(`${LOG_PREFIX} ${COLORS.green}Transformed:${COLORS.reset} ${COLORS.bold}${id}${COLORS.reset}`);
            return {
                code: output.code,
                map: output.map,
            };
        },
    };
}
